-- Christ Way Church Management System base schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists branches(id uuid primary key default gen_random_uuid(),name text unique not null,is_headquarters boolean default false);
insert into branches(name,is_headquarters) values ('Christ Way Church Najjera',true),('Christ Way Church Bulindo',false),('Christ Way Church Kyanjanja',false) on conflict(name) do nothing;
create table if not exists user_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'branch_viewer' check(role in ('super_admin','senior_pastor','branch_pastor','secretary','treasurer','mc_leader','ministry_leader','attendance_officer','data_entry')),branch_id uuid references branches(id),created_at timestamptz default now());
create table if not exists members(id uuid primary key default gen_random_uuid(),full_name text not null,phone text,email text,branch_name text not null default 'Christ Way Church Najjera',branch_id uuid references branches(id),status text default 'Active',created_at timestamptz default now(),created_by uuid references auth.users(id));
create table if not exists attendance(id uuid primary key default gen_random_uuid(),member_id uuid references members(id),service_name text not null,service_date date not null,branch_id uuid references branches(id),created_at timestamptz default now());
create table if not exists visitors(id uuid primary key default gen_random_uuid(),full_name text not null,phone text,visit_date date default current_date,branch_id uuid references branches(id),followup_notes text,created_at timestamptz default now());
create table if not exists missional_communities(id uuid primary key default gen_random_uuid(),name text not null,leader_id uuid references members(id),branch_id uuid references branches(id));
create table if not exists ministries(id uuid primary key default gen_random_uuid(),name text not null,branch_id uuid references branches(id));
create table if not exists funds(id uuid primary key default gen_random_uuid(),name text not null,branch_id uuid references branches(id));
create table if not exists contributions(id uuid primary key default gen_random_uuid(),member_id uuid references members(id),fund_id uuid references funds(id),amount numeric(12,2) not null check(amount>=0),date date default current_date,branch_id uuid references branches(id),created_at timestamptz default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),description text not null,amount numeric(12,2) not null check(amount>=0),date date default current_date,branch_id uuid references branches(id),created_at timestamptz default now());
create table if not exists events(id uuid primary key default gen_random_uuid(),title text not null,event_date date,description text,branch_id uuid references branches(id));
create table if not exists pastoral_care(id uuid primary key default gen_random_uuid(),member_id uuid references members(id),notes text not null,created_at timestamptz default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor uuid references auth.users(id),action text,table_name text,record_id uuid,created_at timestamptz default now());
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from user_profiles where id=auth.uid() $$;
create or replace function public.my_branch() returns uuid language sql stable security definer set search_path=public as $$ select branch_id from user_profiles where id=auth.uid() $$;
create or replace function public.can_access_branch(b uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.my_role()='super_admin' or (public.my_branch()=b and public.my_branch() is not null) $$;
-- Enable RLS on core sensitive tables
alter table user_profiles enable row level security;alter table members enable row level security;alter table attendance enable row level security;alter table visitors enable row level security;alter table contributions enable row level security;alter table expenses enable row level security;alter table pastoral_care enable row level security;alter table branches enable row level security;
create policy "profile self or admin" on user_profiles for select to authenticated using (id=auth.uid() or public.my_role()='super_admin');
create policy "profile admin update" on user_profiles for update to authenticated using (public.my_role()='super_admin');
create policy "branches read" on branches for select to authenticated using (true);
create policy "members branch access" on members for all to authenticated using (public.my_role()='super_admin' or branch_id=public.my_branch()) with check (public.my_role()='super_admin' or branch_id=public.my_branch());
create policy "attendance branch access" on attendance for all to authenticated using (public.my_role()='super_admin' or branch_id=public.my_branch()) with check (public.my_role()='super_admin' or branch_id=public.my_branch());
create policy "visitors branch access" on visitors for all to authenticated using (public.my_role()='super_admin' or branch_id=public.my_branch()) with check (public.my_role()='super_admin' or branch_id=public.my_branch());
create policy "giving treasurer admin" on contributions for all to authenticated using (public.my_role() in ('super_admin','senior_pastor','treasurer') and (public.my_role()='super_admin' or branch_id=public.my_branch())) with check (public.my_role() in ('super_admin','senior_pastor','treasurer') and (public.my_role()='super_admin' or branch_id=public.my_branch()));
create policy "expense treasurer admin" on expenses for all to authenticated using (public.my_role() in ('super_admin','senior_pastor','treasurer') and (public.my_role()='super_admin' or branch_id=public.my_branch())) with check (public.my_role() in ('super_admin','senior_pastor','treasurer') and (public.my_role()='super_admin' or branch_id=public.my_branch()));
create policy "care restricted" on pastoral_care for all to authenticated using (public.my_role() in ('super_admin','senior_pastor','branch_pastor') and (public.my_role()='super_admin' or public.my_branch() is not null)) with check (public.my_role() in ('super_admin','senior_pastor','branch_pastor'));
-- IMPORTANT: policies should be reviewed and refined before real sensitive data is entered.
